import {mountLive} from './live-scene.js';
const $=id=>document.getElementById(id),asset=name=>`/assets/sculptures/${name}.png`;
let weather,place={name:'Rawalpindi',latitude:33.6,longitude:73.067},unit='C',view='now',period='day',selected=0,start=0,request=0;
const fmt=(n,d=0)=>Number.isFinite(n)?n.toFixed(d):'—';const temp=v=>v==null?'—':Math.round(unit==='C'?v:v*9/5+32);const deg=v=>temp(v)+'°'+unit;const direction=v=>['N','NE','E','SE','S','SW','W','NW'][Math.round(v/45)%8];
const description=c=>c===0?'Clear':c<3?'Partly cloudy':c===3?'Overcast':c<50?'Fog':c<60?'Drizzle':c<70?'Rain':c<80?'Snow':c<90?'Showers':'Thunderstorm';const weatherAsset=c=>c<3?'sun':c<50?'cloud':'precip';const glyph=c=>c<3?'☀':c<50?'☁':c<80?'☂':'ϟ';const say=t=>$('status').textContent=t;
const time=t=>{if(!t)return'—';const h=Number(t.slice(11,13));return(h%12||12)+(t.slice(14,16)==='00'?'':':'+t.slice(14,16))+(h<12?'A':'P')};
async function json(url){const r=await fetch(url,{signal:AbortSignal.timeout(18000)});if(!r.ok)throw Error('Service unavailable');return r.json()}
async function load(p){const id=++request;say('Updating your forecast…');try{const q=new URLSearchParams({latitude:p.latitude,longitude:p.longitude,current:'temperature_2m,relative_humidity_2m,apparent_temperature,is_day,weather_code,wind_speed_10m,wind_direction_10m,wind_gusts_10m,precipitation,surface_pressure',hourly:'temperature_2m,apparent_temperature,relative_humidity_2m,dew_point_2m,precipitation_probability,precipitation,weather_code,wind_speed_10m,wind_gusts_10m,wind_direction_10m,visibility,surface_pressure,uv_index',daily:'weather_code,temperature_2m_max,temperature_2m_min,sunrise,sunset,uv_index_max,precipitation_sum,precipitation_probability_max,wind_speed_10m_max,wind_gusts_10m_max',timezone:'auto',forecast_days:7});const data=await json('https://api.open-meteo.com/v1/forecast?'+q);if(id!==request)return;weather=data;place=p;selected=0;start=Math.max(0,data.hourly.time.findIndex(t=>t>=data.current.time.slice(0,13)+':00'));$('place').textContent=p.name;render();renderForecast();say('');}catch{if(id===request)say('Weather is unavailable. Check your connection, then search again.')}}
function digits(target,value){target.setAttribute('aria-label',value+' degrees '+(unit==='C'?'Celsius':'Fahrenheit'));mountLive(target,'digits',value)}
function rows(items,note=''){$('measurements').replaceChildren();for(const [key,value] of items){const r=document.createElement('div');r.className='measure-row';const label=document.createElement('span');label.textContent=key;const line=document.createElement('i');const val=document.createElement('b');val.textContent=value;r.append(label,line,val);$('measurements').append(r)}if(note){const p=document.createElement('p');p.className='measure-note';p.textContent=note;$('measurements').append(p)}}
function selectedData(){const h=weather.hourly,d=weather.daily,c=weather.current;const i=period==='day'?Math.min(start+selected,h.time.length-1):Math.max(0,h.time.findIndex(t=>t===d.time[selected]+'T12:00'));const day=period==='week'?selected:Math.max(0,d.time.indexOf(h.time[i].slice(0,10)));const current=period==='day'&&selected===0;return{i,day,current,t:current?c.temperature_2m:h.temperature_2m[i],code:current?c.weather_code:h.weather_code[i],when:h.time[i]}}
function render(){if(!weather)return;const c=weather.current,h=weather.hourly,d=weather.daily,s=selectedData(),i=s.i;const isNow=view==='now';$('stage').dataset.view=view;$('forecast-section').hidden=!isNow;$('temperature-block').hidden=!isNow;$('detail-content').hidden=isNow;$('view-title').textContent={now:'Your sky.',temp:'Temp',sun:'Sun',air:'Air',moon:'Moon',precip:'Precip'}[view];$('time-label').textContent=period==='day'&&selected===0?'NOW':period==='week'?new Date(d.time[selected]+'T12:00').toLocaleDateString('en',{weekday:'long'}).toUpperCase():time(s.when);$('selected-label').textContent=$('time-label').textContent;$('scrubber').max=period==='day'?23:6;$('scrubber').value=selected;
const sculpture=$('sculpture');if(view==='temp'){mountLive(sculpture,'digits',temp(s.t))}else{const night=s.when<weather.daily.sunrise[s.day]||s.when>weather.daily.sunset[s.day];const name=view==='now'?(night&&s.code<3?'moon':weatherAsset(s.code)):view;mountLive(sculpture,'weather',name)}
if(isNow){digits($('temperature-art'),temp(s.t));$('condition').textContent=description(s.code);$('overview-meta').textContent=`HIGH ${deg(d.temperature_2m_max[s.day])} / LOW ${deg(d.temperature_2m_min[s.day])} · FEELS ${deg(s.current?c.apparent_temperature:h.apparent_temperature[i])}`}
if(view==='temp')rows([['Temperature',deg(s.t)],['High',deg(d.temperature_2m_max[s.day])],['Low',deg(d.temperature_2m_min[s.day])],['Feels like',deg(s.current?c.apparent_temperature:h.apparent_temperature[i])],['Humidity',fmt(h.relative_humidity_2m[i])+'%'],['Dew point',deg(h.dew_point_2m[i])]]);
if(view==='sun')rows([['UV index',fmt(period==='week'?d.uv_index_max[selected]:h.uv_index[i],1)],['Sunrise',time(d.sunrise[s.day])],['Sunset',time(d.sunset[s.day])],['Daylight',daylight(d.sunrise[s.day],d.sunset[s.day])]]);
if(view==='air')rows([['Wind speed',fmt((period==='week'?d.wind_speed_10m_max[selected]:h.wind_speed_10m[i])/3.6,1)+' M/S'],['Wind gust',fmt((period==='week'?d.wind_gusts_10m_max[selected]:h.wind_gusts_10m[i])/3.6,1)+' M/S'],['Direction',direction(h.wind_direction_10m[i])],['Visibility',fmt(h.visibility[i]/1000,1)+' KM'],['Pressure',fmt(h.surface_pressure[i])+' HPA']],period==='week'?'Daily maximum wind and gusts. Other readings at noon.':'');
if(view==='precip')rows([['Precipitation',fmt(period==='week'?d.precipitation_sum[selected]:h.precipitation[i],1)+(period==='week'?' MM/DAY':' MM/HOUR')],['Chance',fmt(period==='week'?d.precipitation_probability_max[selected]:h.precipitation_probability[i])+'%'],['Type',s.code<51?'None':s.code>=71&&s.code<80?'Snow':s.code>=95?'Thunderstorm':'Rain']]);
if(view==='moon'){if(window.SunCalc){const date=utcDate(s.when),m=SunCalc.getMoonIllumination(date),times=SunCalc.getMoonTimes(date,place.latitude,place.longitude);rows([['Illumination',fmt(m.fraction*100)+'%'],['Phase',moonPhase(m.phase)],['Moonrise',astroTime(times.rise)],['Moonset',astroTime(times.set)]],'Astronomical estimates. Moon sculpture is illustrative.')}else rows([['Moon data','Unavailable']]);}
renderChart();$('updated').textContent='UPDATED '+time(c.time)+' · '+weather.timezone.replaceAll('_',' ');}
function daylight(a,b){const m=(new Date(b)-new Date(a))/60000;return Number.isFinite(m)?Math.floor(m/60)+'H '+Math.round(m%60)+'M':'—'}
function utcDate(t){return new Date(Date.parse(t+'Z')-weather.utc_offset_seconds*1000)}
function astroTime(d){return d?new Intl.DateTimeFormat('en-US',{timeZone:weather.timezone,hour:'numeric',minute:'2-digit'}).format(d):'—'}
function moonPhase(p){return p<.03||p>.97?'New moon':p<.22?'Waxing crescent':p<.28?'First quarter':p<.47?'Waxing gibbous':p<.53?'Full moon':p<.72?'Waning gibbous':p<.78?'Last quarter':'Waning crescent'}
function series(){const h=weather.hourly,d=weather.daily,n=period==='day'?24:7;const key={now:'temperature_2m',temp:'temperature_2m',sun:'uv_index',air:'wind_speed_10m',precip:'precipitation'}[view];return Array.from({length:n},(_,j)=>{let v;if(view==='moon'){const t=period==='day'?h.time[start+j]:d.time[j]+'T12:00';v=window.SunCalc?SunCalc.getMoonIllumination(utcDate(t)).fraction*100:0}else if(period==='day')v=h[key][start+j];else v=d[{now:'temperature_2m_max',temp:'temperature_2m_max',sun:'uv_index_max',air:'wind_speed_10m_max',precip:'precipitation_sum'}[view]][j];if(view==='now'||view==='temp')return unit==='F'?v*9/5+32:v;if(view==='air')return v/3.6;return v})}
function renderChart(){const values=series(),n=values.length;let low=Math.min(...values),high=Math.max(...values);if(['sun','precip','air','moon'].includes(view))low=0;if(high-low<1)high=low+1;const W=400,H=100,xx=j=>8+j/(n-1)*348,yy=v=>90-(v-low)/(high-low)*78;const points=values.map((v,j)=>`${xx(j).toFixed(1)},${yy(v).toFixed(1)}`).join(' ');const sel=Math.min(selected,n-1);$('chart').innerHTML=`<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" aria-hidden="true"><line x1="8" y1="91" x2="356" y2="91" stroke="#ededed"/><polyline pathLength="1" points="${points}" fill="none" stroke="#272727" stroke-width="2.8" stroke-linejoin="round" stroke-linecap="round"/><line x1="${xx(sel)}" y1="8" x2="${xx(sel)}" y2="94" stroke="#ddd" stroke-dasharray="2 4"/><circle cx="${xx(sel)}" cy="${yy(values[sel])}" r="4" fill="#ff1235"/><text x="368" y="16">${Math.round(high)}</text><text x="368" y="55">${Math.round((high+low)/2)}</text><text x="368" y="94">${Math.round(low)}</text></svg>`;$('chart').setAttribute('aria-label',`${view} forecast: ${values.map(v=>fmt(v,1)).join(', ')}`);$('chart-label').textContent={now:'TEMPERATURE / °'+unit,temp:'TEMPERATURE / °'+unit,sun:'UV INDEX',air:'WIND / M/S',moon:'ILLUMINATION / %',precip:'PRECIPITATION / MM'}[view];const ticks=period==='day'?[0,6,12,18,23]:[0,2,4,6];$('time-ticks').replaceChildren();for(const j of ticks){const span=document.createElement('span');span.textContent=period==='day'?(j===0?'NOW':time(weather.hourly.time[start+j])):(j===0?'TODAY':new Date(weather.daily.time[j]+'T12:00').toLocaleDateString('en',{weekday:'short'}).toUpperCase());$('time-ticks').append(span)}}
function renderForecast(){const h=weather.hourly,d=weather.daily;$('hourly').innerHTML=Array.from({length:12},(_,j)=>start+j*2).map((i,j)=>`<div class="hour"><span>${j===0?'NOW':time(h.time[i])}</span><span class="forecast-symbol" role="img" aria-label="${description(h.weather_code[i])}">${glyph(h.weather_code[i])}</span><strong>${temp(h.temperature_2m[i])}°</strong><small>${h.precipitation_probability[i]}%</small></div>`).join('');$('daily').innerHTML=d.time.map((t,i)=>`<div class="day"><span class="mono">${i===0?'TODAY':new Date(t+'T12:00').toLocaleDateString('en',{weekday:'short'}).toUpperCase()}</span><span class="forecast-symbol" role="img" aria-label="${description(d.weather_code[i])}">${glyph(d.weather_code[i])}</span><strong>${temp(d.temperature_2m_max[i])}°</strong><em>${temp(d.temperature_2m_min[i])}°</em></div>`).join('')}
function setView(v){view=v;selected=0;document.querySelectorAll('[data-view]').forEach(b=>{if(b.tagName==='BUTTON'){if(b.dataset.view===v)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')}});$('stage').classList.remove('switching');void $('stage').offsetWidth;$('stage').classList.add('switching');render();window.dispatchEvent(new Event('atmos-view'));}
document.querySelectorAll('.view-nav button').forEach(b=>b.onclick=()=>setView(b.dataset.view));function setPeriod(p){period=p;selected=0;document.querySelectorAll('[data-period]').forEach(b=>b.classList.toggle('active',b.dataset.period===p));$('period-toggle').classList.toggle('week',p==='week');$('period-toggle').setAttribute('aria-label','Switch to '+(p==='day'?'weekly':'daily')+' forecast');render()}document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>setPeriod(b.dataset.period));$('period-toggle').onclick=()=>setPeriod(period==='day'?'week':'day');$('scrubber').oninput=e=>{$('stage').classList.remove('switching');selected=Number(e.target.value);render()};
$('place-button').onclick=()=>{$('search-panel').hidden=!$('search-panel').hidden;if(!$('search-panel').hidden)$('query').focus()};document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('search-panel').hidden=true;$('place-button').focus()}});document.addEventListener('click',e=>{if(!$('search-panel').contains(e.target)&&!$('place-button').contains(e.target))$('search-panel').hidden=true});
let searchId=0;$('search').onsubmit=async e=>{e.preventDefault();const q=$('query').value.trim();if(q.length<2)return;const id=++searchId;say('Finding places…');$('results').replaceChildren();try{const data=await json('https://geocoding-api.open-meteo.com/v1/search?'+new URLSearchParams({name:q,count:6,language:'en',format:'json'}));if(id!==searchId)return;if(!data.results?.length){say('No places found. Try another city.');return}for(const p of data.results){const b=document.createElement('button');b.className='results-button';b.textContent=[p.name,p.admin1,p.country].filter(Boolean).join(', ');b.onclick=()=>{$('search-panel').hidden=true;load(p)};$('results').append(b)}say('Choose your city.')}catch{if(id===searchId)say('Search is unavailable. Please try again.')}};
$('units').onclick=()=>{unit=unit==='C'?'F':'C';$('units').innerHTML=unit==='C'?'°C <span>/ °F</span>':'°F <span>/ °C</span>';$('units').setAttribute('aria-label','Switch to '+(unit==='C'?'Fahrenheit':'Celsius'));if(weather){render();renderForecast()}};
$('locate').onclick=()=>{if(!navigator.geolocation){say('Location is not supported. Search for a city instead.');return}say('Waiting for location permission…');$('locate').disabled=true;navigator.geolocation.getCurrentPosition(p=>{$('locate').disabled=false;$('search-panel').hidden=true;load({name:'Current location',latitude:p.coords.latitude,longitude:p.coords.longitude})},e=>{$('locate').disabled=false;say(e.code===1?'Location denied. Enable it in browser settings or search for a city.':'Location unavailable. Please search for a city.')},{enableHighAccuracy:false,timeout:12000,maximumAge:300000})};

load(place);setInterval(()=>{if(!document.hidden)load(place)},600000);
